static constexpr size_t kAtlasCount = 8;

const Atlas* Find(uint8_t size, bool bold) {
    for (size_t i = 0; i < kAtlasCount; ++i) {
        if (kAtlases[i].size == size && kAtlases[i].bold == bold) {
            return &kAtlases[i];
        }
    }
    return nullptr;
}

const Glyph* FindGlyph(const Atlas& atlas, uint32_t codepoint) {
    if (codepoint > 0xffffu) return nullptr;
    uint16_t lo = 0;
    uint16_t hi = atlas.glyph_count;
    while (lo < hi) {
        const uint16_t mid = static_cast<uint16_t>(lo + (hi - lo) / 2);
        const uint16_t here = atlas.glyphs[mid].codepoint;
        if (here == codepoint) return &atlas.glyphs[mid];
        if (here < codepoint) {
            lo = static_cast<uint16_t>(mid + 1);
        } else {
            hi = mid;
        }
    }
    return nullptr;
}

